"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
import {readCashierLedgerMappings} from '@/lib/cashier-ledger-mappings';
import {readCashierVariancePostingPreview} from '@/lib/cashier-variance-posting';
import {CashierLedgerMappingSelect} from './cashier-ledger-mapping-select';
import {CashierLedgerPeriodSelect} from './cashier-ledger-period-select';
import {CashierVariancePostingAction} from './cashier-variance-posting-action';
type Mapping=ReturnType<typeof readCashierLedgerMappings>['entries'][number];
export function CashierVariancePostingReview({scope,session,bank,amount}:{scope:HandoffScope;session:string;bank:string;amount:string}){
 const [mapping,setMapping]=useState<Mapping|null>(null),[setup,setSetup]=useState<AccountingSetup|null>(null),[expense,setExpense]=useState(''),[posting,setPosting]=useState<{period:string;date:string}|null>(null),[preview,setPreview]=useState<Record<string,unknown>|null>(null),[pending,setPending]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');const alive=useRef(false),lock=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 const selection=mapping&&expense&&posting?{scope,session,mapping:mapping.id,expense,cash:mapping.custody.id,amount,...posting}:null;
 async function run(kind:'accounts'|'preview'){if(lock.current||pending)return;lock.current=true;setBusy(true);setError('');setPreview(null);if(kind==='accounts'){setExpense('');setSetup(null)}try{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh cash accounting.');
 const args={p_tenant:scope.tenant,p_property:scope.property};let accounts:AccountingSetup|null=null,result:Record<string,unknown>|null=null;
 if(kind==='accounts')accounts=readAccountingSetup(await hotelRpc('gl_setup',args),scope.tenant,scope.property);else{if(!selection)throw Error('Choose accounts and a posting date.');result=readCashierVariancePostingPreview(await hotelRpc('preview_cashier_variance',{...args,p_session:session,p_mapping:selection.mapping,p_expense:selection.expense,p_period:selection.period,p_date:selection.date}),selection)}
 const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Refresh cash accounting.');if(alive.current){if(accounts)setSetup(accounts);if(result)setPreview(result)}
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to prepare the variance adjustment.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <details><summary>Post drawer variance adjustment</summary><p>Drawer variance: {usd(Number(amount))}. A manager must review the variance and mark it as requiring an accounting adjustment.</p><CashierLedgerMappingSelect scope={scope} bank={bank} disabled={busy||pending} onSelect={v=>{setMapping(v);setPreview(null)}}/><button type="button" disabled={busy||pending} onClick={()=>void run('accounts')}>Load expense accounts</button>{setup&&<label>Cash short or over account<select disabled={busy||pending} value={expense} onChange={e=>{setExpense(e.target.value);setPreview(null)}}><option value="">Choose a cash short or over expense account</option>{setup.accounts.filter(a=>a.active&&a.kind==='expense').map(a=><option key={a.account_id} value={a.account_id}>{a.code} {a.name}</option>)}</select></label>}<CashierLedgerPeriodSelect scope={scope} disabled={busy||pending} onSelect={v=>{setPosting(v);setPreview(null)}}/><button type="button" disabled={!selection||busy||pending} onClick={()=>void run('preview')}>Preview variance adjustment</button>{error&&<p role="alert">{error}</p>}{preview&&<section aria-label="Variance adjustment preview"><p>{BigInt(amount)>BigInt(0)?'Credit':'Debit'} {setup?.accounts.find(a=>a.account_id===expense)?.name}: {usd(Math.abs(Number(amount)))}</p><p>{BigInt(amount)>BigInt(0)?'Debit':'Credit'} {mapping?.custody.name}: {usd(Math.abs(Number(amount)))}</p><p>Posting date: {posting?.date}</p></section>}<CashierVariancePostingAction scope={scope} session={session} selection={selection} preview={preview} onPending={setPending}/></details>
}
